  "prompt": "prompts/physics_committee_terra_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction supplied the essential physical principles for reliable quantum information despite decoherence.",
        "attribution": "Shor established the transformative error-correction framework, Steane made codes operationally powerful, and Kitaev provided decisive topological fault-tolerance concepts.",
        "maturity": "The ideas have shaped all major hardware platforms and are now being tested through increasingly substantial logical-qubit demonstrations.",
        "uncertainties": [
          "Large-scale fault-tolerant computation has not yet been achieved."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED made strong, controllable light-matter interaction on a chip into a robust experimental regime and changed quantum-device physics.",
        "attribution": "Blais supplied a foundational dispersive-theory formulation, while Wallraff and Schoelkopf established its compelling experimental realization.",
        "maturity": "It is reproducible across laboratories and underlies much of present superconducting quantum science.",
        "uncertainties": [
          "Credit also extends importantly to Steven M. Girvin and to a broad experimental lineage."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B018",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have enabled a qualitatively new precision frontier, with consequences for timekeeping, metrology and fundamental tests.",
        "attribution": "Katori originated the magic-wavelength lattice-clock concept and Ye drove major precision and performance advances.",
        "maturity": "Independent systems have repeatedly achieved extraordinary accuracy and are approaching practical redefinition-level capability.",
        "uncertainties": [
          "The eventual institutional adoption of optical clocks as the primary time standard remains incomplete."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B020",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Their theoretical architecture for trapped-ion processing and simulation made quantum information a concrete laboratory physics programme.",
        "attribution": "Cirac and Zoller form an unusually clear and tightly linked partnership between seminal proposals and the field they initiated.",
        "maturity": "The proposals have been realized and generalized across leading ion-trap experiments over decades.",
        "uncertainties": [
          "The contribution overlaps conceptually with wider quantum-information theory and experimental ion-trap development."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B023",
      "proposed_laureates": [
        "Mikhail D. Lukin",
        "Antoine Browaeys",
        "Philippe Grangier"
      ],
      "assessment": {
        "nobel_worthiness": "Rydberg blockade turned neutral atoms into programmable, strongly interacting quantum many-body systems with remarkable control.",
        "attribution": "Lukin supplied central blockade and many-body concepts, while Browaeys and Grangier made decisive experimental advances.",
        "maturity": "Large coherent arrays and reproducible analog simulation now demonstrate the robustness of the platform.",
        "uncertainties": [
          "The division of priority among the several foundational theory and experiment groups needs particularly careful examination."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Christian J. Bordé",
        "Mark A. Kasevich",
        "David E. Pritchard"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry provided an exceptionally sensitive quantum-mechanical method for measuring inertial and gravitational quantities.",
        "attribution": "Bordé developed central interferometric concepts, and Kasevich and Pritchard drove landmark precision implementations.",
        "maturity": "Its methods are long established, widely reproduced and influential in precision measurement.",
        "uncertainties": [
          "The appropriate boundary between atom interferometry and the broader atomic-precision-measurement tradition is not sharp."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B043",
      "proposed_laureates": [
        "Markus Aspelmeyer",
        "Tobias J. Kippenberg",
        "Andrew N. Cleland"
      ],
      "assessment": {
        "nobel_worthiness": "Ground-state cooling and coherent control of mechanical modes made a mesoscopic mechanical system manifestly quantum.",
        "attribution": "Aspelmeyer, Kippenberg and Cleland each made central experimental and conceptual contributions to modern quantum optomechanics.",
        "maturity": "Ground-state preparation, measurement backaction and quantum control have been convincingly reproduced in diverse architectures.",
        "uncertainties": [
          "The field has several indispensable pioneers, making a three-person attribution difficult."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Jian-Wei Pan"
      ],
      "assessment": {
        "nobel_worthiness": "Multiphoton entanglement and satellite links made quantum communication a strikingly capable physical technology over unprecedented distances.",
        "attribution": "Pan has provided unusually sustained leadership spanning multiphoton experiments, quantum repeaters and satellite demonstrations.",
        "maturity": "The experiments are technically mature and independently influential, though satellite communication remains an evolving platform.",
        "uncertainties": [
          "The nomination combines several related achievements and may underrepresent foundational contributors to quantum communication."
        ]
      }
    }
  ]
}
